import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import axios from 'axios';
import Modal from 'react-modal';
import 'tailwindcss/tailwind.css'; // Import Tailwind CSS

Modal.setAppElement('#root');

const HomePage = () => {
  const location = useLocation();
  const [userInfo, setUserInfo] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [folderName, setFolderName] = useState('');
  const [isCreateModalOpen, setIsCreateModalOpen] = useState(false);
  const [isRetrieveModalOpen, setIsRetrieveModalOpen] = useState(false);
  const [folders, setFolders] = useState([]);
  const [selectedFolder, setSelectedFolder] = useState('');

  useEffect(() => {
    const fetchUserInfo = async () => {
      try {
        const accessToken = location.state.accessToken;
        const response = await axios.get('http://localhost:3001/salesforce/user-info', {
          params: { accessToken },
        });
        setUserInfo(response.data);
      } catch (error) {
        setError('Failed to load user information.');
      }
    };

    fetchUserInfo();
  }, [location.state.accessToken]);

  const handleOpenCreateModal = () => setIsCreateModalOpen(true);
  const handleCloseCreateModal = () => {
    setIsCreateModalOpen(false);
    setFolderName('');
  };

  const handleCreateFolder = async () => {
    if (!folderName) {
      setMessage('Please enter a folder name.');
      return;
    }
    
    setLoading(true);
    setMessage('');
    try {
      const response = await axios.get('http://localhost:3001/createFolder', {
        params: { folderName },
      });
      setMessage(response.data.message);
      handleCloseCreateModal();
    } catch (error) {
      setMessage('Failed to create folder.');
    } finally {
      setLoading(false);
    }
  };

  const handleOpenRetrieveModal = async () => {
    setLoading(true);
    try {
      const response = await axios.get('http://localhost:3001/listFolders');
      setFolders(response.data.folders);
      setIsRetrieveModalOpen(true);
    } catch (error) {
      setMessage('Failed to fetch folders.');
    } finally {
      setLoading(false);
    }
  };

  const handleCloseRetrieveModal = () => {
    setIsRetrieveModalOpen(false);
    setSelectedFolder('');
  };

  const handleRetrieveApexClass = async () => {
    if (!selectedFolder) {
      setMessage('Please select a folder.');
      return;
    }

    setLoading(true);
    setMessage('');
    try {
      const response = await axios.get('http://localhost:3001/retrieveApexClass', {
        params: { folderName: selectedFolder },
      });
      setMessage(response.data.message);
      handleCloseRetrieveModal();
    } catch (error) {
      setMessage('Failed to retrieve Apex class.');
    } finally {
      setLoading(false);
    }
  };

  const handleDeployApexClass = async () => {
    setLoading(true);
    setMessage('');
    try {
      const response = await axios.get('http://localhost:3001/deployApexClass');
      setMessage(response.data.message);
    } catch (error) {
      setMessage('Failed to deploy Apex class.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col items-center p-5 min-h-screen bg-gray-100">
      <div className="bg-white p-6 rounded-lg shadow-lg w-full max-w-4xl">
        {error ? (
          <p className="text-red-500">{error}</p>
        ) : userInfo ? (
          <div className="bg-gray-800 text-white p-5 rounded-lg mb-6">
            <p>User ID: {userInfo.user_id}</p>
            <p>Name: {userInfo.name}</p>
            <p>Email: {userInfo.email}</p>
          </div>
        ) : (
          <p>Loading user information...</p>
        )}
        <div className="flex flex-col space-y-4">
          <button 
            onClick={handleOpenCreateModal} 
            disabled={loading}
            className="py-2 px-4 bg-blue-500 text-white rounded-lg"
          >
            Create Deployment Folder
          </button>
          <button 
            onClick={handleOpenRetrieveModal} 
            disabled={loading}
            className="py-2 px-4 bg-blue-500 text-white rounded-lg"
          >
            Retrieve Apex Class
          </button>
          <button 
            onClick={handleDeployApexClass} 
            disabled={loading}
            className="py-2 px-4 bg-blue-500 text-white rounded-lg"
          >
            Deploy Apex Class
          </button>
        </div>
        {message && <p className="mt-4 text-red-500">{message}</p>}
      </div>
      
      <Modal
        isOpen={isCreateModalOpen}
        onRequestClose={handleCloseCreateModal}
        contentLabel="Enter Folder Name"
        className="bg-white p-6 rounded-lg shadow-lg w-full max-w-md mx-auto"
        overlayClassName="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center"
      >
        <h2 className="text-xl mb-4">Enter Folder Name</h2>
        <input 
          type="text" 
          placeholder="Enter folder name" 
          value={folderName} 
          onChange={(e) => setFolderName(e.target.value)} 
          className="w-full p-2 mb-4 border rounded-lg"
        />
        <div className="flex justify-between">
          <button 
            onClick={handleCreateFolder} 
            disabled={loading}
            className="py-2 px-4 bg-blue-500 text-white rounded-lg"
          >
            Create
          </button>
          <button 
            onClick={handleCloseCreateModal}
            className="py-2 px-4 bg-gray-500 text-white rounded-lg"
          >
            Cancel
          </button>
        </div>
      </Modal>

      <Modal
        isOpen={isRetrieveModalOpen}
        onRequestClose={handleCloseRetrieveModal}
        contentLabel="Select Folder"
        className="bg-white p-6 rounded-lg shadow-lg w-full max-w-md mx-auto"
        overlayClassName="fixed inset-0 bg-black bg-opacity-50 flex justify-center items-center"
      >
        <h2 className="text-xl mb-4">Select Folder to Retrieve Apex Class</h2>
        <select 
          value={selectedFolder}
          onChange={(e) => setSelectedFolder(e.target.value)}
          className="w-full p-2 mb-4 border rounded-lg"
        >
          <option value="" disabled>Select a folder</option>
          {folders.map(folder => (
            <option key={folder} value={folder}>{folder}</option>
          ))}
        </select>
        <div className="flex justify-between">
          <button 
            onClick={handleRetrieveApexClass} 
            disabled={loading}
            className="py-2 px-4 bg-blue-500 text-white rounded-lg"
          >
            Retrieve
          </button>
          <button 
            onClick={handleCloseRetrieveModal}
            className="py-2 px-4 bg-gray-500 text-white rounded-lg"
          >
            Cancel
          </button>
        </div>
      </Modal>
    </div>
  );
};

export default HomePage;
